from typing import Sequence

def fixed(p: Sequence[int]) -> set[int]: return {i for i,x in enumerate(p) if i==x}

def conjugate(p: Sequence[int], e: Sequence[int]) -> tuple[int,...]:
    inv=[0]*len(e)
    for old,new in enumerate(e): inv[new]=old
    return tuple(e[p[inv[t]]] for t in range(len(p)))

p=(1,2,0,3,4); e=(4,2,0,1,3); q=conjugate(p,e)
print("original:",fixed(p),"transported:",fixed(q))
assert fixed(q)=={e[x] for x in fixed(p)}

