from typing import Sequence

def transport_loop(p: Sequence[int], e: Sequence[int]) -> tuple[int,...]:
    if sorted(p)!=list(range(len(p))) or sorted(e)!=list(range(len(e))) or len(p)!=len(e):
        raise ValueError("equal-size permutations required")
    inverse=[0]*len(e)
    for old,new in enumerate(e): inverse[new]=old
    return tuple(e[p[inverse[new]]] for new in range(len(p)))

from typing import Sequence

def involution_parity_certificate(p: Sequence[int]) -> tuple[list[int], list[tuple[int,int]]]:
    if any(p[p[x]]!=x for x in range(len(p))): raise ValueError("map is not involutive")
    fixed=[]; pairs=[]
    for x,y in enumerate(p):
        if x==y: fixed.append(x)
        elif x<y: pairs.append((x,y))
    assert len(p)==len(fixed)+2*len(pairs)
    return fixed,pairs

